function init(eli) {
  // ELI Agent: Revise Document and Address Comments, its plan, review and apply engine (tools/eli_agent parts 12, 20,
  // 40, 50, 55, 65b, 71, 75, 75h, 76, 77, 78) in a bundle of its own (docs/ELI_AGENT_SPLIT_PLAN.md step 5). ELI Agent,
  // the host, hands over what it uses (H): the run, its screens and areas, and the shared helpers below, by name. Beside
  // an ELI Agent that doesn't hand over every one of them (one that still holds Revise itself: an older one, or one
  // reverted to it) this bundle does nothing.
  var H = typeof eli.dispatch === "function" ? eli.dispatch("eli_agent", "host") : null;
  // A newer ELI Agent started in this session (an update installed while ELI was open): this bundle starts again
  // beside it, and this copy stops listening. Listened for even while it does nothing, so a host that arrives later
  // gets it too.
  var reattach = eli.bus && typeof eli.bus.on === "function" ? eli.bus.on("eli_agent:host", function (e) {
    if (!e || !e.host || e.host === H) return;
    if (typeof reattach === "function") reattach();
    init(eli);
  }) : null;
  if (!H || !(H.apiVersion >= 1) || !H.fn) return;
  var RE_REDLINE_MARK = H.fn.RE_REDLINE_MARK, _aiJsonCall = H.fn._aiJsonCall, _bodyHeader = H.fn._bodyHeader,
    _cleanView = H.fn._cleanView, _closeAgentOverlay = H.fn._closeAgentOverlay, _dtMatch = H.fn._dtMatch,
    _egArea = H.fn._egArea, _egNorm = H.fn._egNorm, _egRun = H.fn._egRun, _egScreen = H.fn._egScreen,
    _egSides = H.fn._egSides, _egStartArea = H.fn._egStartArea, _esc = H.fn._esc, _findAgent = H.fn._findAgent,
    _flat = H.fn._flat, _getAgentSettings = H.fn._getAgentSettings, _guidanceBlock = H.fn._guidanceBlock,
    _loadPlaybookSnippets = H.fn._loadPlaybookSnippets, _markupView = H.fn._markupView, _originalView = H.fn._originalView, _readRow = H.fn._readRow,
    _readText = H.fn._readText, _redlineAuthors = H.fn._redlineAuthors,
    _relabelExecutionBlock = H.fn._relabelExecutionBlock, _renderOverlayBody = H.fn._renderOverlayBody,
    _renderStream = H.fn._renderStream, _reviewed = H.fn._reviewed, _runPlaybookPass = H.fn._runPlaybookPass,
    _scrollIntoView = H.fn._scrollIntoView, _scrollSoon = H.fn._scrollSoon, _stageStrip = H.fn._stageStrip,
    _stream = H.fn._stream, _truncate = H.fn._truncate, _wireCancelOnly = H.fn._wireCancelOnly,
    _pbPositionsFor = H.fn._pbPositionsFor, _pbHoldEdits = H.fn._pbHoldEdits, _pbStrong = H.fn._pbStrong, PB_CAP = H.fn.PB_CAP,   // [PB-MATCH]
    _tdIsOwner = H.fn._tdIsOwner;   // [BLOCKS-OPEN] the owner first
  // [REPLAY] the owner's replay (a host without it: no Replay button, the rest as before)
  var _egReplayStart = H.fn._egReplayStart, _egReplayReady = H.fn._egReplayReady, _rpClarify = H.fn._rpClarify;
  // [IN-PLACE] the cards' editor, Respond's (a host without it: this bundle does nothing, as for any helper it lacks)
  var _egInPlace = H.fn._egInPlace, _egCaretAt = H.fn._egCaretAt, _egTokenDiff = H.fn._egTokenDiff,
    _egMarkedHtml = H.fn._egMarkedHtml, _egRegenWords = H.fn._egRegenWords, _egErr = H.fn._egErr, _egAskClause = H.fn._egAskClause, _egAskLine = H.fn._egAskLine, _egWriteLineHtml = H.fn._egWriteLineHtml, _egWriteBar = H.fn._egWriteBar;
  if ([_egInPlace, _egCaretAt, _egTokenDiff, _egMarkedHtml, _egRegenWords, _egErr, _egAskClause, _egAskLine, _egWriteLineHtml, _egWriteBar, RE_REDLINE_MARK, _aiJsonCall, _bodyHeader, _cleanView, _closeAgentOverlay, _dtMatch, _egArea, _egNorm, _egRun,
    _egScreen, _egSides, _egStartArea, _esc, _findAgent, _flat, _getAgentSettings, _guidanceBlock,
    _loadPlaybookSnippets, _markupView, _originalView, _readRow, _readText, _redlineAuthors, _relabelExecutionBlock,
    _renderOverlayBody, _renderStream, _reviewed, _runPlaybookPass, _scrollIntoView, _scrollSoon, _stageStrip,
    _stream, _truncate, _wireCancelOnly, _egReplayStart, _egReplayReady, _rpClarify, _pbPositionsFor, _pbHoldEdits, _pbStrong, PB_CAP, _tdIsOwner].indexOf(undefined) >= 0) return;

  function _bodyApplying() {
    var run = _egRun(), L = run && run.applyLive;
    if (!L) return _bodyHeader() + '<div class="_eg_status_box"><div class="_eg_status_dot"></div><div>Applying redlines to the document…</div></div>';
    return _bodyHeader() + _rvWriteBoxHtml(run);
  }
  // [RV-BOX] The writing list, in the team's box under the chart as Respond's is ([BOX]; the owner, 10-23: "the step 4
  // writer part should stream something in the streaming box, just like Respond does") — and on the plain screen.
  function _rvWriteBoxHtml(run) {
    return '<div class="_td_inbox"><div id="_rv_whead">' + _rvWriteHeadHtml(run.applyLive) + '</div><div class="_td_wl" id="_rv_wl">' + _rvWriteRows(run) + '</div></div>';
  }
  // ─── [RV-WRITE] ───────────────────────────────────────────────────
  // Applying, as it happens (the owner's rule: a step at work is never a bare spinner — 24 renames took 10-18 s, a
  // shortened section 38-44 s, behind "Applying redlines…"). Every accepted edit in the order Word writes them, each a
  // digest (where · Change / Add / Remove; the words struck → written; why); the one Word is writing marked, ✓ as each
  // lands, ⚠ and the reason when one doesn't; a counter and the clock; then "Reading it back…" while the written clauses
  // are checked. Respond's writing-stream look (the host's stylesheet), painted in place so the list never jumps.
  var RV_WRITE_ACT = { replace: ["Change", "Changed"], insert: ["Add", "Added"], "delete": ["Remove", "Removed"], sigblock: ["Add", "Added"], definition: ["Add", "Added"], story: ["Change", "Changed"] };   // story: [RV-HF] a header or footer line
  function _rvWriteStart(accepted) {
    var run = _egRun();
    if (!run) return;
    run.applyLive = { t0: Date.now(), ids: accepted.map(function (e) { return e.id; }), st: {}, why: {}, phase: "write" };
    accepted.forEach(function (e) { run.applyLive.st[e.id] = "wait"; });
    if (!run._rvTick) run._rvTick = setInterval(function () {
      if (!_egRun() || _egRun() !== run || run.status !== "applying") { clearInterval(run._rvTick); run._rvTick = null; return; }
      var h = document.getElementById("_rv_whead");
      if (h) h.innerHTML = _rvWriteHeadHtml(run.applyLive);
    }, 1000);
  }
  function _rvWriteMark(id, st, why) {
    var L = _egRun() && _egRun().applyLive;
    if (!L || !(id in L.st)) return;
    L.st[id] = st;
    if (why) L.why[id] = why;
    _rvWritePaint(id);
    _rvTeamPing();
  }
  function _rvWritePhase(phase) { var L = _egRun() && _egRun().applyLive; if (!L) return; L.phase = phase; _rvWritePaint(); _rvTeamPing(); }
  // [WRITER-TEAM] With the team on screen, each change landing (and the read-back starting) reaches it at once: Writer,
  // its Formatter and its Read-back report as they go, and the writing phase is never a still screen (the owner, 10-22).
  // A repaint keeps the team's screen in place ([TEAM-KEEP]); it costs nothing next to the Word write.
  function _rvTeamPing() { var r = _egRun(); if (r && r._team && r._team.ctl && r.status === "applying") _renderOverlayBody(); }
  function _rvWriteHeadHtml(L) {
    var n = L.ids.length, done = L.ids.filter(function (id) { return L.st[id] === "done" || L.st[id] === "warn"; }).length;
    var s = Math.max(0, Math.floor((Date.now() - L.t0) / 1000)), clock = Math.floor(s / 60) + ":" + ("0" + s % 60).slice(-2);
    return _egWriteBar(done, n, (L.phase === "check" ? "Reading the written clauses back · " + done + " of " + n + " written" : "Writing " + Math.min(done + 1, n) + " of " + n + " into Word") + " · " + clock);
  }
  // A change as the shared line draws it ([WRITE-LINE]): only the words that change, with three either side ("…and
  // Supplier → O'Reilly have entered…"); a new clause or a cut, its words.
  function _rvWriteLineHtml(e, st, why) {
    var was = _egNorm(e._anchoredText || e.anchorText || ""), now = _egNorm(e.replacementText || ""), change;
    if (e.type === "insert" || e.type === "sigblock" || e.type === "noticeblock" || e.type === "definition") change = { ins: _truncate(now, 140) };
    else if (e.type === "delete") change = { del: _truncate(was, 140) };
    else {
      var A = was.split(" "), B = now.split(" "), i = 0, j = 0;
      while (i < A.length && i < B.length && A[i] === B[i]) i++;
      while (j < A.length - i && j < B.length - i && A[A.length - 1 - j] === B[B.length - 1 - j]) j++;
      change = { pre: (i > 3 ? "…" : "") + A.slice(Math.max(0, i - 3), i).join(" "), del: _truncate(A.slice(i, A.length - j).join(" "), 90), ins: _truncate(B.slice(i, B.length - j).join(" "), 90),
        post: B.slice(B.length - j, B.length - j + 3).join(" ") + (j > 3 ? "…" : "") };
    }
    var past = st === "done" || st === "warn";
    return _egWriteLineHtml({ key: e.id, sec: e.section || e.paragraphId || "", act: past ? "accept" : "counter", change: change, why: why ? _truncate(why, 160) : "", miss: st === "warn" ? "Not applied" : "" },
      st, RV_WRITE_ACT[e.type] || RV_WRITE_ACT.replace);
  }
  function _rvWriteRows(run) {
    var L = run.applyLive, byId = {};
    ((run.plan && run.plan.edits) || []).forEach(function (e) { byId[e.id] = e; });
    return L.ids.filter(function (id) { return byId[id]; }).map(function (id) { return _rvWriteLineHtml(byId[id], L.st[id], L.why[id] || byId[id].rationale || ""); }).join("");
  }
  // One row (or only the header) repainted where it stands; the row Word is on kept in view, a third of the way down.
  function _rvWritePaint(id) {
    var run = _egRun(), L = run && run.applyLive, wl = document.getElementById("_rv_wl"), h = document.getElementById("_rv_whead");
    if (!L || !wl) return;
    if (h) h.innerHTML = _rvWriteHeadHtml(L);
    if (id) {
      var e = ((run.plan && run.plan.edits) || []).filter(function (x) { return x.id === id; })[0], row = wl.querySelector('[data-td-wl="' + id + '"]');
      if (e && row) row.outerHTML = _rvWriteLineHtml(e, L.st[id], L.why[id] || e.rationale || "");
    }
    var cur = wl.querySelector("._td_wl_cur");
    if (cur) wl.scrollTop = Math.max(0, cur.offsetTop - wl.clientHeight / 3);
  }
  // ─── [/RV-WRITE] ──────────────────────────────────────────────────
  function _bodyApplied() {
    var r = _egRun().applyResult || { applied: 0, failures: [], appliedEdits: [] };
    var appliedEdits = r.appliedEdits || [];
    // Group applied edits by section for the same orientation users
    // already learned in the review view.
    var groups = {};
    var groupOrder = [];
    appliedEdits.forEach(function (e) {
      var key = e.section || e.category || "Other";
      if (!groups[key]) { groups[key] = []; groupOrder.push(key); }
      groups[key].push(e);
    });
    var listHtml = '';
    if (appliedEdits.length) {
      listHtml = '<div class="_eg_section_label" style="margin-top:14px;">APPLIED EDITS (' + appliedEdits.length + ')</div>' +
        '<div class="_eg_prop_hint">Click any row to find it in the document.</div>' +
        groupOrder.map(function (g) {
          return '<div class="_eg_group">' +
            '<div class="_eg_group_header">' + _esc(g) + ' <span class="_eg_group_count">(' + groups[g].length + ')</span></div>' +
            groups[g].map(function (e) { return _appliedRowHtml(e); }).join("") +
          '</div>';
        }).join('');
    }
    var failHtml = "";
    if (r.failures && r.failures.length) {
      failHtml = '<div class="_eg_section_label" style="margin-top:14px;">NOT APPLIED (' + r.failures.length + ')</div>' +
        '<div class="_eg_prop_hint">These were not written to the document. ' +
        'Each one shows what it would have changed, so you can make it by hand.</div>' +
        r.failures.map(function (f) {
          return _failCardHtml(f);
        }).join("");
    }
    var pa = _egRun().postAudit;
    var canRecheck = (_egRun().requirements || []).length && !(pa && pa.running);
    // [CALM-END] with the team signed off above: the offer and a re-check in view, the rest behind Details
    var calm = !!(_egRun()._team && _egRun()._team.ctl);
    return _bodyHeader() +
      (calm ? _commentOfferHtml(appliedEdits) + _renderPostAuditSection(pa) + '<details class="_eg_calm_details"><summary>Changes written (' + appliedEdits.length + ')</summary>' : '') +
      '<div class="_eg_applied_box">' +
        '<div class="_eg_applied_title">✓ Applied ' + r.applied + ' redline' + (r.applied === 1 ? "" : "s") + ' to the document.</div>' +
        '<div class="_eg_applied_sub">Word now shows them as tracked changes — accept/reject in the Review pane.</div>' +
      '</div>' +
      (calm ? '' : _commentOfferHtml(appliedEdits) + _renderPostAuditSection(pa)) +
      listHtml +
      failHtml +
      // At the BOTTOM of the revisions, not above them: you read what went
      // into the document, then what is left for you. Entering this screen
      // scrolls here, so the list is behind you by the time you arrive.
      _renderFollowUpSection(
        (_egRun().plan && _egRun().plan.edits) || appliedEdits,
        _egRun().plan || {}) +
      (calm ? _runTimeHtml(_egRun()) + '</details>' : '') +
      '<div class="_eg_actions_row _eg_actions_sticky">' +
        '<button id="_eg_new_plan" type="button" class="_eg_btn_secondary">New Plan</button>' +
        (typeof _egReplayReady === "function" && _egReplayReady() ? '<button id="_eg_replay" type="button" class="_eg_btn_secondary" title="Run this again from its recording — no AI calls">↻ Replay</button>' : '') +   // [REPLAY]
        (canRecheck
          ? '<button id="_eg_post_audit" type="button" class="_eg_btn_secondary" ' +
            'title="Re-read the document and re-check it against your request">🔍 ' +
            (pa ? 'Re-check again' : 'Check the document') + '</button>'
          : '') +
        // Email-agent only: surface the response-email generator on the applied page.
        (_egRun().agent === "address_comments"
          ? '<button id="_eg_gen_response_email" type="button" class="_eg_btn_secondary">📧 Generate response email</button>'
          : '') +
        '<button id="_eg_close_done" type="button" class="_eg_btn_primary">Done</button>' +
      '</div>';
  }
  // [RUN-TIME] Where the run's time went, from the kernel's timings since it began: the whole, the AI's (summed — some
  // calls run side by side) and Word's. Shapes only.
  function _runTimeHtml(run) {
    var t0 = run && run._t0, all = [];
    try { all = ((eli.perf && eli.perf.timings && eli.perf.timings()) || {}).entries || []; } catch (_) { all = []; }
    if (!t0) return "";
    var mine = all.filter(function (e) { return e && e.at >= t0; }), sum = function (k) { return mine.filter(function (e) { return e.kind === k; }).reduce(function (n, e) { return n + (e.ms || 0); }, 0); };
    var ai = mine.filter(function (e) { return e.kind === "ai"; }).length, fmt = function (ms) { var s = Math.round(ms / 1000); return s >= 60 ? Math.floor(s / 60) + " min " + (s % 60) + " s" : s + " s"; };
    return '<div class="_eg_run_time">This run: ' + fmt(Date.now() - t0) + ' · AI ' + fmt(sum("ai")) + ' over ' + ai + ' call' + (ai === 1 ? "" : "s") + ' · Word ' + fmt(sum("word")) + '</div>';
  }
  // The re-check, on the applied screen. Same checklist as the pre-apply
  // audit, scored against the document instead of against a simulation —
  // so it reuses the same renderer.
  function _renderPostAuditSection(pa) {
    if (!pa) return "";
    if (pa.running) {
      return '<div class="_eg_audit_box">' +
        '<div class="_eg_audit_head">Re-reading the document and checking it against ' +
        'your request…</div>' +
      '</div>';
    }
    if (pa.error) {
      return '<div class="_eg_audit_box">' +
        '<div class="_eg_audit_head">⚠ Re-check did not run</div>' +
        '<div class="_eg_audit_row"><span class="_eg_audit_text">' + _esc(pa.error) +
        ' — what is in the document has NOT been checked against your request.' +
        '</span></div>' +
      '</div>';
    }
    return _renderCoverageSection(pa) +
      (pa.fixNote ? '<div class="_eg_audit_box"><div class="_eg_audit_row"><span class="_eg_audit_text">' + _esc(pa.fixNote) + '</span></div></div>' : "") +   // [PA-HANDOVER]
      (pa.handedOver ? '<div class="_eg_audit_box"><div class="_eg_audit_row"><span class="_eg_audit_text">' + pa.handedOver + " change" + (pa.handedOver === 1 ? "" : "s") +
        " the check would make " + (pa.handedOver === 1 ? "is" : "are") + " in a notice or signature block, which ELI doesn't edit: make " + (pa.handedOver === 1 ? "it" : "them") + " by hand in Word.</span></div></div>" : "") +
      (pa.gaps && pa.gaps.length && !pa.fixNote
        ? '<div class="_eg_actions_row" style="padding-top:0;">' +
          '<button id="_eg_fix_gaps" type="button" class="_eg_btn_primary">Plan ' +
          pa.gaps.length + ' fix' + (pa.gaps.length === 1 ? "" : "es") + ' →</button>' +
        '</div>'
        : "");
  }
  // Compact applied-edit row — section + paragraph + tiny inline-style
  // diff + Locate button. Reads as a confirmation list, not a review
  // card (these have already happened, no decisions to make).
  // "INSERT" said nothing about what was being inserted. Every insert adds a
  // whole new section now, so the badge says so.
  function _typeBadge(e) {
    var t = (e && e.type) || "replace";
    return '<span class="_eg_type_badge _eg_type_' + t + '">' +
      _esc(t === "insert" ? "NEW SECTION" : t === "sigblock" ? "SIGNATURE BLOCK" : t === "noticeblock" ? "NOTICE BLOCK" : t === "definition" ? "DEFINITION" : t === "story" ? (e._story && e._story.kind === "footer" ? "FOOTER" : "HEADER") : t.toUpperCase()) + '</span>';
  }
  function _appliedRowHtml(e) {
    var typeBadge = _typeBadge(e);
    var paraLine = "";
    if (e.paragraphIndex && e.paragraphTotal) {
