    }
    var change = "";
    if (e.type === "delete") {
      change = '<del class="_eg_inline_del">' + _esc(_truncate(e.anchorText, 90)) + '</del>';
    } else if (e.type === "insert") {
      change = '<span class="_eg_applied_inserts">+ ' + _esc(_truncate(e.replacementText, 90)) + '</span>';
    } else {
      change =
        '<del class="_eg_inline_del">' + _esc(_truncate(e.anchorText, 60)) + '</del>' +
        ' <ins class="_eg_inline_ins">' + _esc(_truncate(e.replacementText, 60)) + '</ins>';
    }
    // A heading ELI wrote was restyled to match the document's others.
    // That is a formatting change the user did not ask for, so it is said
    // rather than left to be noticed.
