      title: "Title Case", sentence: "Sentence case" };
    var hm = e._headingMatched
      ? '<div class="_eg_applied_fmt">Heading matched to the document' +
        (e._headingMatched.style
          ? ' (' + _esc(e._headingMatched.style) + ')'
          : ((e._headingMatched.facets || []).length
              ? ' (' + _esc(e._headingMatched.facets.join(", ")) + ')' : "")) +
        (e._headingMatched.recased
          ? ' · recased to ' + _esc(hmCase[e._headingMatched.recased] ||
              e._headingMatched.recased) : "") +
        ((e._headingMatched.para || []).length ? ' · kept its alignment' : "") +
        '</div>'
      : "";
