    // sentence with a bolded term in the middle loses it. Say so — the
    // alternative is the user finding out by reading.
    var ff = (e._formattingFlattened || []).length
      ? '<div class="_eg_applied_fmt">' + (e._leadKept
          ? 'The heading “' + _esc(e._leadKept) + '” kept its formatting; any other mixed ' +
            _esc(e._formattingFlattened.join(" and ")) + ' in the clause was not carried over — re-apply it if it mattered.'
          : 'The original mixed ' + _esc(e._formattingFlattened.join(" and ")) +
            ' could not be kept through the replacement — re-apply it if it mattered.') + '</div>'
      : "";
    // The row locates, like the review cards. A button for the action you
