    var dbl = e._doubled ? '<div class="_eg_applied_fmt">Now reads “' + _esc(_truncate(e._doubled, 80)) + '” twice in a row — check this clause.</div>' : "";
    // [KEEP-HEADING] The draft restated the heading with small changes nobody asked for.
