    return '<div class="_eg_applied_row _eg_card_clickloc" data-eg-applied-id="' + _esc(e.id) + '" data-eg-applied-locate="' + _esc(e.id) + '" title="Click to find this in the document">' +
      '<div class="_eg_applied_meta">' + typeBadge + paraLine + '</div>' +
