  // so "that that" or "(a) (a)" don't count.
  function _dupRun(text) {
    var w = String(text || "").split(/\s+/).filter(Boolean);
    for (var n = Math.min(12, Math.floor(w.length / 2)); n >= 2; n--) {
      for (var i = 0; i + 2 * n <= w.length; i++) {
