    findings.notInParagraph = [];
    findings.multiLine = [];
    findings.anchorTooLong = [];
    findings.paragraphRebuilt = [];
    findings.listLabels = [];
    findings.retargeted = [];
    findings.multiParagraph = [];
    findings.paragraphsMerged = [];
    findings.rebuiltFromClean = [];
    findings.breaksLost = [];
    findings.multiLineWrites = [];
    (edits || []).forEach(function (e) {
      if (e._precision !== "exact") {
        findings.unanchored.push({ id: e.id, precision: e._precision, section: e.section || "" });
      }
      if (e._wholeParagraph) findings.wholeParagraph.push(e.section || e.id);
      if (e._multiLineAnchor) findings.multiLine.push(e.section || e.id);
      if (e._lineBreaksLost) findings.breaksLost.push(e.section || e.id);
      if (e._insertedLines > 1) {
