  // Which paragraphs the edits landed in, so the reading has a focus. An
  // insert has no paragraph of its own in the index, so its neighbour is
  // named instead — which is where the seam it creates will be.
  function _dmTouched(edits) {
    var seen = {}, out = [];
    (edits || []).forEach(function (e) {
      var id = e && e.paragraphId;
      if (!id || seen[id]) return;
      seen[id] = true;
      out.push(id);
    });
    return out;
  }

  // [RV-EARLY] The damage check's prompt for the edits as they stand (null: nothing to check).
  function _damageAsk() {
    if (!_egRun() || !_egRun().plan) return null;
    var edits = _egRun().plan.edits || [];
    if (!edits.length) return null;
    var payload = _simulatedPayload(edits);
    return payload.length ? _buildDamagePrompt(_egRun(), payload, _dmTouched(edits)) : null;
  }
  function _runDamageCheck() {
    var ask = _damageAsk();
    if (!ask) return Promise.resolve(null);
    _egRun().status = "proofread";
    _stream("stage", "Proof-reading the result",
      "what the edits may have broken, rather than what they were for");
    _renderOverlayBody();
    return _rvCall(ask, { problems: "object" })   // [RV-EARLY] started beside coverage
      .then(function (r) {
        if (!_egRun()) return null;
        var list = (r && Array.isArray(r.problems)) ? r.problems : [];
        var problems = list.map(function (p) {
          return {
            where: String((p && p.where) || "").slice(0, 80),
            what: String((p && p.what) || "").trim().slice(0, 300),
            quote: String((p && p.quote) || "").trim().slice(0, 300),
            alsoAt: String((p && p.alsoAt) || "").trim().slice(0, 120),
            severity: /^(high|medium|low)$/.test(String(p && p.severity))
              ? p.severity : "medium",
          };
        }).filter(function (p) { return p.what; });
