  // a bigger liberty than leaving a note.
  function _renderDamageSection(d) {
    if (!d) return "";
    if (d.failed) {
      return '<div class="_eg_dm_panel _eg_dm_failed">' +
        '<div class="_eg_dm_head">Proof-read did not run</div>' +
        '<div class="_eg_dm_note">The check for what these edits might have ' +
          'broken failed. The edits themselves are unaffected — but nothing ' +
          'has read the result as a finished document.</div>' +
      '</div>';
    }
    if (!d.ran) return "";
    if (!d.problems.length) {
      return '<div class="_eg_dm_panel _eg_dm_clean">' +
        '<div class="_eg_dm_head">Proof-read clean</div>' +
        '<div class="_eg_dm_note">Read back as a finished document, the edits ' +
          'do not repeat anything already there, contradict anything untouched, ' +
          'or leave a sentence dangling.</div>' +
      '</div>';
