  function _simulatedPayload(edits) {
    var paras = (_egRun() && _egRun().qaIndex) || [];
    var sim = _simulate(paras.map(function (p) {
      return { id: p.id, anchor: p.id, text: _readText(p) };
    }), edits || []);
    return sim.filter(function (p) { return String(p.text || "").trim(); })
      .map(function (p) { return { id: p.id, text: p.text }; });
  }

  // Break the instruction into the things that must be TRUE of the finished
