      "{",
      '  "achieved": true|false,',
      '  "assessment": "1-2 sentences: does this document now do what was asked?",',
      '  "checklist": [',
      '    { "id": "r1", "satisfied": false,',
      '      "evidence": "by and between Colgate and Lipotype",',
      '      "note": "the preamble still names two parties" }',
      "  ],",
      '  "edits": [',
      '    { "id": "c1", "type": "replace", "paragraphId": "ELI_IDX_1",',
      '      "section": "Preamble", "anchorText": "<verbatim text from the document below>",',
      '      "replacementText": "<the corrected text>",',
