  }

  // One round. Resolves with the NEW edits it proposes (possibly none).
  function _runCoverageRound(round, stalled) {
    if (!_egRun()) return Promise.resolve([]);
    var payload = _simulatedPayload(_egRun().plan.edits);
    if (!payload.length) return Promise.resolve([]);
    var prompt = _buildCoveragePrompt(_egRun(), payload, _egRun().verification,
      round, null, stalled);
    return _aiJsonCall(prompt,
      { achieved: "boolean", assessment: "string", checklist: "object", edits: "object" })
      .then(function (r) {
        if (!_egRun() || !r) return [];
        // Score the checklist by id so the review shows which requirements
        // are met and which are not — the audit IS the output, not just the
        // edits it produces.
        var byId = {};
        (Array.isArray(r.checklist) ? r.checklist : []).forEach(function (c) {
          if (c && c.id) byId[c.id] = c;
