            String(req.text || "") + " " + String(req.where || ""));
          return {
            id: req.id, text: req.text, where: req.where || "",
            // Unreported is NOT satisfied. A requirement the audit skipped
            // must never read as met.
            satisfied: c.satisfied === true,
            // Not the agent's to satisfy: a notice or signature block.
            handover: handover || null,
            reported: Object.prototype.hasOwnProperty.call(byId, req.id),
            evidence: String(c.evidence || "").slice(0, 200),
            note: String(c.note || "").slice(0, 200),
          };
        });
        var openGaps = scored.filter(function (x) { return !x.satisfied && !x.handover; }).length;
        var byHand = scored.filter(function (x) { return !x.satisfied && x.handover; }).length;
        _stream(openGaps ? "warn" : "ok",
          "Audit round " + round + (openGaps ? ": " + openGaps + " gap" +
            (openGaps === 1 ? "" : "s") : ": clean") +
            (byHand ? " (+" + byHand + " for you by hand)" : ""),
          String(r.assessment || "").slice(0, 120));
        _egRun().coverage = {
          round: round,
          // ONE definition of clean, used by the round's own line and by the
          // verdict that ends the loop. They disagreed: the line counted
          // open gaps, the verdict also deferred to the model's own
